/**
 * PayPal's Server SDK as generated by APIMatic (package `paypal`, from APIMatic's Context Plugin for
 * PayPal), for the reporting side: Transaction Search and Balances. Payouts and Log in with PayPal
 * are not in this SDK, so they stay on our own client (`client.ts`). Sandbox only.
 *
 * Built from the contract sheet in `paypal-plan.md`: one client, held; the SDK's default retries for
 * reads with a 20 s per-attempt timeout; request logging forced off.
 */

import { PaypalClient } from "paypal";
import { fromMoney } from "./money.ts";

export type HistoryTransaction = {
  id: string;
  eventCode: string;
  amountCents: number;
  currency: string;
  /** S = completed, P = pending, D = denied, V = reversed. */
  status: string;
  note: string;
};

/** PayPal's transaction history and balances: what reconciliation and the funding check need. */
export interface PayPalReporting {
  /** Transactions in [start, end] (at most 31 days), every page, and when PayPal last refreshed them. */
  history(start: Date, end: Date): Promise<{ refreshedAt: string | null; transactions: HistoryTransaction[] }>;
  /** Available balance in `currency`, in cents, or null if PayPal reports none. */
  available(currency: string): Promise<number | null>;
}

export type ReportingOptions = {
  clientId: string;
  clientSecret: string;
  /** "sandbox" or unset; anything else is refused, because the SDK's only host is the sandbox. */
  environment?: string;
  timeoutMs?: number;
  /** Tests only: a fake transport. */
  fetch?: typeof fetch;
  maxRetries?: number;
};

const MAX_PAGES = 50;

export function sdkReporting(options: ReportingOptions): PayPalReporting {
  if ((options.environment ?? "sandbox") !== "sandbox") throw new Error("Rightful only talks to the PayPal sandbox. Set PAYPAL_ENV=sandbox.");
  // An unset credential is not an SDK error (the call would just 401 later), so check it here.
  if (!options.clientId || !options.clientSecret) throw new Error("Set PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET.");
  const client = new PaypalClient({
    oauth2: { clientId: options.clientId, clientSecret: options.clientSecret },
    retry: { timeout: options.timeoutMs ?? 20_000, ...(options.maxRetries === undefined ? {} : { maxRetries: options.maxRetries }) },
    // Responses carry account IDs and balances: keep logging off whatever PAYPAL_CLIENT_LOG says.
    logging: { level: "off" },
    ...(options.fetch ? { fetch: options.fetch } : {}),
  });
  const iso = (d: Date) => d.toISOString().replace(/\.\d+Z$/, "Z");

  return {
    async history(start, end) {
      const transactions: HistoryTransaction[] = [];
      let refreshedAt: string | null = null;
      for (let page = 1; page <= MAX_PAGES; page++) {
        const result = await client.transactionSearch.searchTransactions({
          startDate: iso(start),
          endDate: iso(end),
          fields: "transaction_info",
          pageSize: 500,
          page,
        });
        refreshedAt = result.lastRefreshedDatetime ?? refreshedAt;
        for (const detail of result.transactionDetails ?? []) {
          const info = detail.transactionInfo;
          if (!info?.transactionId || !info.transactionAmount) continue;
          transactions.push({
            id: info.transactionId,
            eventCode: info.transactionEventCode ?? "",
            amountCents: signedCents(info.transactionAmount.currencyCode, info.transactionAmount.value),
            currency: info.transactionAmount.currencyCode,
            status: info.transactionStatus ?? "",
            note: info.transactionNote ?? info.transactionSubject ?? "",
          });
        }
        if (page >= (result.totalPages ?? 1)) break;
      }
      return { refreshedAt, transactions };
    },
    async available(currency) {
      const result = await client.transactionSearch.searchBalances({ currencyCode: currency });
      const balance = result.balances?.find((b) => b.currency === currency);
      return balance?.availableBalance ? fromMoney({ currency_code: currency, value: balance.availableBalance.value }) : null;
    },
  };
}

/** Transaction Search signs amounts: a payout is a debit such as "-1.00". */
export function signedCents(currency: string, value: string): number {
  const negative = value.startsWith("-");
  const cents = fromMoney({ currency_code: currency, value: negative ? value.slice(1) : value });
  return negative ? -cents : cents;
}
